-- [questID] = { [objectiveIndex] = { creatureIDs } } where ATT names no creature
ns.SPAWN_PROVIDERS = {
[22]={[1]={157,454,547}},
[86]={[1]={113,119,524}},
}
-- objectives without a creature get these (map, minimap, nameplates and tooltips use them)
ns.ATT_OBJECTIVES = ns.ATT_OBJECTIVES or {}
for questID, objs in pairs(ns.SPAWN_PROVIDERS) do
  local q = ns.ATT_OBJECTIVES[questID] or {}
  ns.ATT_OBJECTIVES[questID] = q
  for index, ids in pairs(objs) do
    local o = q[index] or { {}, {}, {} }
    q[index] = o
    o[1] = o[1] or {}
    if #o[1] == 0 then for _, id in ipairs(ids) do o[1][#o[1] + 1] = id end end
  end
end
